from pathlib import Path
p=Path('backend/src/controllers/categoryController.js');s=p.read_text(encoding='utf-8').replace("const db = require('../config/db');", "const db = require('../config/db');\nconst { logAudit } = require('../utils/auditLog');")
s=s.replace("    return res.status(201).json({ category: result.rows[0] });", "    await logAudit(req, { action: 'Category created', entityType: 'service_category', entityLabel: result.rows[0].name });\n    return res.status(201).json({ category: result.rows[0] });")
s=s.replace('RETURNING id\', [id]', 'RETURNING id, name\', [id]')
s=s.replace("    return res.json({ success: true });", "    await logAudit(req, { action: 'Category removed', entityType: 'service_category', entityLabel: `${result.rows[0].name} — services moved to Other` });\n    return res.json({ success: true });")
p.write_text(s,encoding='utf-8')
p=Path('backend/src/controllers/serviceController.js');s=p.read_text(encoding='utf-8').replace("const db = require('../config/db');", "const db = require('../config/db');\nconst { logAudit } = require('../utils/auditLog');")
s=s.replace("    return res.status(201).json({ service: full.rows[0] });", "    await logAudit(req, { action: 'Service created', entityType: 'service', entityLabel: `${full.rows[0].name} · ${full.rows[0].price} TZS · ${full.rows[0].duration_minutes} min`, branchId: full.rows[0].branch_id });\n    return res.status(201).json({ service: full.rows[0] });")
s=s.replace("    const sets = [];", "    const previous = await db.query('SELECT * FROM services WHERE id = $1', [id]);\n    if (!previous.rows.length) return res.status(404).json({ error: 'Service not found.' });\n    const sets = [];")
s=s.replace("    return res.json({ service: full.rows[0] });", "    const current = full.rows[0];\n    const labels = { name: 'Name', duration_minutes: 'Duration (min)', price: 'Price (TZS)', is_active: 'Available', category_id: 'Category ID', branch_id: 'Branch ID' };\n    const changes = Object.entries(labels).filter(([key]) => Object.prototype.hasOwnProperty.call(req.body, key) && String(previous.rows[0][key]) !== String(current[key])).map(([key, label]) => `${label}: ${previous.rows[0][key] ?? 'None'} → ${current[key] ?? 'None'}`);\n    if (Object.prototype.hasOwnProperty.call(req.body, 'description') && previous.rows[0].description !== current.description) changes.push('Description updated');\n    if (changes.length) await logAudit(req, { action: 'Service updated', entityType: 'service', entityLabel: `${current.name} · ${changes.join('; ')}`, branchId: current.branch_id });\n    return res.json({ service: current });")
p.write_text(s,encoding='utf-8')
